package com.bookrush.publisherservice.api;
import java.security.Principal; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/publisher") public class PublisherController { private final JdbcTemplate jdbc; public PublisherController(JdbcTemplate jdbc){this.jdbc=jdbc;} private String s(Principal p){if(p==null||p.getName()==null||p.getName().isBlank()) throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"authentication required"); return p.getName();} public record Submission(String title){}
 @PostMapping("/submissions") public Object create(@RequestBody Submission req,Principal p){UUID id=UUID.randomUUID();jdbc.update("insert into publisher.submission(id,subject_key,title) values(?,?,?)",id,s(p),req.title());return Map.of("id",id,"title",req.title(),"status","DRAFT");}
 @PostMapping("/submissions/{id}/submit") public Object submit(@PathVariable UUID id,Principal p){int n=jdbc.update("update publisher.submission set status='SUBMITTED',updated_at=now() where id=? and subject_key=?",id,s(p));return n==0?Map.of("error","NOT_FOUND"):Map.of("id",id,"status","SUBMITTED");}
 @GetMapping("/submissions") public Object list(Principal p){return jdbc.queryForList("select id,title,status,created_at,updated_at from publisher.submission where subject_key=? order by created_at desc",s(p));}
}
